    gap: 10px;
  }
`;
const OldPrice = styled.span`
  font-size: 12px;
  color: #9ca3af;
  text-decoration: line-through;
`;
const NowPrice = styled.span`
  font-size: 16px;
  font-weight: 700;
  color: #111827;
`;
const SrOnly = styled.span`
  ${srOnly}
`;
const AddToCart = styled.button<{ $disabled: boolean }>`
  margin-top: auto;
  position: relative;
  border: none;
  border-radius: 6px;
  padding: 8px 12px;
  font-size: 14px;
  font-weight: 600;
  color: #fff;
  background: #2563eb;
  cursor: pointer;
  transition: background-color 0.15s ease;
  @media (hover: hover) {
    &:hover:not(:disabled) {
      background: #1d4ed8;
    }
  }
  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }
  ${desktop} {
    padding: 9px 12px;
  }
  ${focusRing}
  ${minTargetSize}
  ${({ $disabled }) =>
    $disabled &&
    css`
      background: #d1d5db;
      color: #6b7280;
      cursor: not-allowed;
    `}
`;

interface Product {
  i: number;
  title: string;
  price: number;
  discount: number;
  rating: number;
  inStock: boolean;
  wishlisted: boolean;
}

const Tile: FunctionComponent<{ p: Product }> = ({ p }) => (
  <Card>
    <ImageWrap>
      <ImagePlaceholder aria-hidden="true" />
      {p.discount > 0 && (
        <Badge $high={p.discount >= 30}>
          <SrOnly>Reduced by </SrOnly>-{p.discount}%
        </Badge>
      )}
      <Wishlist
        $on={p.wishlisted}
        type="button"
        aria-pressed={p.wishlisted}
        aria-label={p.wishlisted ? "Remove from wishlist" : "Add to wishlist"}
      >
        <span aria-hidden="true">♥</span>
      </Wishlist>
    </ImageWrap>
    <Title>{p.title}</Title>
    <Rating role="img" aria-label={`Rated ${p.rating} out of 5`}>
      <RatingFill aria-hidden="true" $pct={(p.rating / 5) * 100} />
    </Rating>
    <PriceRow>
      {p.discount > 0 && (
        <OldPrice>
          <SrOnly>Was </SrOnly>${(p.price * (1 + p.discount / 100)).toFixed(2)}
        </OldPrice>
      )}
      <NowPrice>
        {p.discount > 0 && <SrOnly>Now </SrOnly>}${p.price.toFixed(2)}
      </NowPrice>
    </PriceRow>
    <AddToCart
      $disabled={!p.inStock}
      disabled={!p.inStock}
      aria-label={p.inStock ? `Add ${p.title} to cart` : `${p.title} is sold out`}
    >
      {p.inStock ? "Add to cart" : "Sold out"}
    </AddToCart>
  </Card>
);

export default (i: number) => {
  const p: Product = {
    i,
    title: "Product " + i,
    price: (i % 50) + 9.99,
    discount: i % 4 === 0 ? (i % 3 === 0 ? 40 : 20) : 0,
    rating: (i % 5) + 1,
    inStock: i % 7 !== 0,
    wishlisted: i % 6 === 0,
  };
  return <Tile p={p} />;
};

