  ${desktop} {
    font-size: 14px;
    line-height: 20px;
    padding: 1px 11px;
    display: inline-flex;
    width: auto;
  }
  &:active:not(:disabled) {
    box-shadow: 0px 0px 2px rgba(0, 0, 0, 0.16), 0px 2px 4px rgba(0, 0, 0, 0.08);
  }
  &::before {
    content: "";
    position: absolute;
