    $variant === "primary"
      ? css`
          &,
          &:link,
          &:visited {
            color: #fff;
            background-color: #444;
          }
          &:hover:not(:active, :disabled),
          &:focus-visible:not(:active, :disabled) {
            background-color: #000;
          }
        `
      : css`
          &,
          &:link,
          &:visited {
            color: #000;
            background-color: #eee;
          }
