      ${() => $variant === 'ghost' && css`background-color:transparent;color:#2563eb;`}
      ${() => $fullWidth && css`width:100%;`}
    `}>{children}</button>
);

export default (i: number) => {
  const variant = (['primary', 'secondary', 'ghost'] as const)[i % 3];
