// styled-components — the DenseButton. Identical CSS to every other lane; the
// difference is the runtime: styled-components resolves these nested rules and
// injects CSS at render. Default-exports a single-instance render(i) (§6); the
// harness loops it. realistic-button varies variant/disabled/icon by index.
import React from "react";
import { css, styled } from "styled-components";

const desktop = "@media (min-width: 992px)";

const StyledButton = styled.button<{ $variant: "standard" | "primary" }>`
  font-size: 16px;
  line-height: 24px;
  letter-spacing: 0.01em;
  font-weight: 400;
  display: flex;
  width: 100%;
  border: 1px solid rgba(0, 0, 0, 0.2);
  border-radius: 3px;
  align-items: center;
  justify-content: center;
  text-align: center;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  padding: 7px 15px;
