    font-size: 14px;
    line-height: 20px;
  }
}
.tab::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  border-bottom: 3px solid transparent;
  transition: opacity 150ms linear;
}
.tab::before {
  position: absolute;
  content: "";
  width: 100%;
  min-width: 40px;
  top: 0;
  bottom: 0;
  height: 100%;
}
.tab:focus-visible {
